/**
 * Flappybird lockstep 运行时（技术方案 §4.2/§4.3/§5.2）。
 *
 * 与原 wxbird.js 的差别：
 *  - 物理不再由 setInterval 驱动；每次收到 `op=step` 才推进固定 tick 数；
 *  - 观测换成主 schema 的命名字段（bird_y/gap_top/gap_bottom/pipe_x）；
 *  - score 是原始累计游戏分数，reward 留给 Python 侧统一计算（§4.2）；
 *  - 渲染是独立的 60fps 循环，只读状态，绝不推进逻辑。
 */

'use strict';

var envcore = require('./envcore.js');
var wemical = require('./wemical.js');

var WORLD_WIDTH = envcore.WORLD_WIDTH;
var WORLD_HEIGHT = envcore.WORLD_HEIGHT;
var GROUND_Y = envcore.GROUND_Y;
var TICKS_PER_STEP = 3;              // §4.3：一次 agent step 最多 3 个物理 tick

function WxBirdRuntime(opts) {
    opts = opts || {};
    this.ctx = opts.ctx;
    this.canvasId = opts.id || 'birdId';
    this.width = opts.width || WORLD_WIDTH;
    this.height = opts.height || WORLD_HEIGHT;
    this.serverUrl = opts.serverUrl || 'ws://localhost:17911';
    this.deathReason = 'none';

    this.engine = new envcore.FlappyEngine(1);
    // 小游戏/小程序的 ctx.drawImage 需要 Image 对象，不能传路径字符串。
    // 原版 wxbird.js 也是先 new Image()（在 Background/Bird 构造里）再画。
    var base = opts.imageBase || '../../images/';
    this.images = {
        bg: this._loadImage(base + 'bg.png'),
        ground: this._loadImage(base + 'ground.png'),
        pipe: this._loadImage(base + 'pipe.png'),
        birds: [this._loadImage(base + '0.gif'), this._loadImage(base + '1.gif'),
                this._loadImage(base + '2.gif')]
    };
    this.birdIndex = 0;

    var self = this;
    this.client = new wemical.WemiCalClient({
        gameId: 'Flappybird',
        url: this.serverUrl,
        envHash: opts.envHash || 'flappybird-lockstep-v1',
        onRequest: function (msg) { return self._onRequest(msg); }
    });
    this.client.connect();
    // render:false 时不起渲染循环（Node 测试用），逻辑不受影响
    if (opts.render !== false) { this._startRenderLoop(); }
}

WxBirdRuntime.prototype._loadImage = function (src) {
    var img = new Image();
    img.src = src;
    return img;
};

// ---------------------------------------------------------------- 请求处理
WxBirdRuntime.prototype._onRequest = function (msg) {
    if (msg.op === 'reset') {
        var seed = (msg.seed === undefined || msg.seed === null) ? 1 : msg.seed;
        this.engine.reset(seed);
        this.deathReason = 'none';
        return this._snapshot(false, 'none');
    }
    if (msg.op === 'step') {
        var action = msg.action;
        if (action !== 0 && action !== 1) {
            // 非法动作不 clamp：直接抛出，让 Python 侧看到协议错误
            throw new Error('Flappybird 非法动作: ' + action);
        }
        var r = this.engine.stepLockstep(action, TICKS_PER_STEP);
        var reason = 'none';
        if (r.dead) {
            reason = this._deathReason();
            this.deathReason = reason;
        }
        return this._snapshot(r.dead, reason);
    }
    throw new Error('未知 op: ' + msg.op);
};

/** 碰撞原因：落地 vs 撞管道（§4.2 的 termination_reason 枚举）。 */
WxBirdRuntime.prototype._deathReason = function () {
    var b = this.engine.bird;
    if (b.by + b.bheight > GROUND_Y) { return 'ground'; }
    return 'collision';
};

/** 主 schema 的 4 个命名字段（§5.2）。 */
WxBirdRuntime.prototype._observation = function () {
    var e = this.engine;
    return {
        bird_y: e.bird.by / WORLD_HEIGHT,
        gap_top: e.up_pipe.pheight / WORLD_HEIGHT,
        gap_bottom: e.down_pipe.py / WORLD_HEIGHT,
        pipe_x: e.up_pipe.px / WORLD_WIDTH
    };
};

WxBirdRuntime.prototype._snapshot = function (terminated, reason) {
    var e = this.engine;
    return {
        obs: this._observation(),
        score: e.score,                       // 原始累计分数，不是训练奖励
        terminated: !!terminated,
        terminationReason: reason,
        simTicks: e.ticks
    };
};

// ---------------------------------------------------------------- 渲染（只读）
//
// 渲染节流到 **25fps（40ms）**，与原版 setInterval(..., 40) 同节奏：
// 在真机上 step 之间的墙钟只有 ~0.3ms，若不节流，画面会以几千帧/秒狂刷，
// 看起来像小鸟在瞬移（"速度非常快"）。逻辑时钟不受这里影响——它只由 op=step 驱动。
var RENDER_INTERVAL_MS = 40;

WxBirdRuntime.prototype._startRenderLoop = function () {
    var self = this;
    function frame() {
        try {
            self._render();
        } catch (err) {
            console.error('[flappy] render error: ' + (err && err.stack ? err.stack : err));
        }
        setTimeout(frame, RENDER_INTERVAL_MS);
    }
    setTimeout(frame, RENDER_INTERVAL_MS);
};

WxBirdRuntime.prototype._render = function () {
    var e = this.engine;
    var ctx = this.ctx;
    ctx.clearRect(0, 0, this.width, this.height);
    ctx.drawImage(this.images.bg, 0, 0, this.width, this.height);
    ctx.drawImage(this.images.pipe, 150, 500, 150, 800,
                  e.up_pipe.px, e.up_pipe.py, e.up_pipe.pwidth, e.up_pipe.pheight);
    ctx.drawImage(this.images.pipe, 0, 500, 150, 500,
                  e.down_pipe.px, e.down_pipe.py, e.down_pipe.pwidth, e.down_pipe.pheight);
    ctx.drawImage(this.images.ground, 0, GROUND_Y, this.width, 200);
    this.birdIndex = (this.birdIndex + 1) % 3;
    ctx.drawImage(this.images.birds[this.birdIndex],
                  e.bird.bx, e.bird.by, e.bird.bwidth, e.bird.bheight);
    ctx.setFillStyle('#ffffff');
    ctx.setFontSize(30);
    if (e.score > 0) { ctx.fillText(String(e.score), 180, 100); }
    if (e.stoped) {
        ctx.setFontSize(24);
        ctx.fillText('score: ' + e.score, 120, 160);
    }
    // 一次性提交绘制操作
    if (typeof ctx.getActions === 'function') {
        wx.drawCanvas({ canvasId: this.canvasId, actions: ctx.getActions() });
    }
};

module.exports = { WxBirdRuntime: WxBirdRuntime, TICKS_PER_STEP: TICKS_PER_STEP };
